def eulerian_number(n, m):
    # Base cases
    if n == 0 and m == 0:
        return 1
    if n > 0 and m == 0:
        return 0
    if n == 1 and m == 1:
        return 1

    # Initialize the Eulerian triangle
    eulerian_triangle = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the first row of the triangle
    eulerian_triangle[0][0] = 1

    # Fill the rest of the triangle
    for i in range(1, n + 1):
        eulerian_triangle[i][0] = i * eulerian_triangle[i - 1][0]
        for j in range(1, i):
            eulerian_triangle[i][j] = eulerian_triangle[i - 1][j - 1] + (i - 1) * eulerian_triangle[i - 1][j]

